import java.util.*;

class Solution {
    public double frogPosition(int n, int[][] edges, int t, int target) {
        if (n == 1) return 1.0;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        boolean[] visited = new boolean[n + 1];
        Queue<int[]> nodeQ = new LinkedList<>();
        Queue<Double> probQ = new LinkedList<>();
        nodeQ.offer(new int[]{1, 0});
        probQ.offer(1.0);
        visited[1] = true;

        while (!nodeQ.isEmpty()) {
            int[] curr = nodeQ.poll();
            int u = curr[0], time = curr[1];
            double p = probQ.poll();

            int unvisitedCount = 0;
            for (int v : adj.get(u)) {
                if (!visited[v]) unvisitedCount++;
            }

            if (u == target) {
                if (time == t || (time < t && unvisitedCount == 0)) return p;
                return 0.0;
            }
            if (time >= t) continue;

            if (unvisitedCount > 0) {
                double nextP = p / unvisitedCount;
                for (int v : adj.get(u)) {
                    if (!visited[v]) {
                        visited[v] = true;
                        nodeQ.offer(new int[]{v, time + 1});
                        probQ.offer(nextP);
                    }
                }
            }
        }
        return 0.0;
    }
}

