double frogPosition(int n, int** edges, int edgesSize, int* edgesColSize, int t, int target) {
    if (n == 1) return 1.0;
    int* deg = (int*)calloc(n + 1, sizeof(int));
    for (int i = 0; i < edgesSize; i++) {
        deg[edges[i][0]]++;
        deg[edges[i][1]]++;
    }
    int** adj = (int**)malloc((n + 1) * sizeof(int*));
    int* ptr = (int*)calloc(n + 1, sizeof(int));
    for (int i = 1; i <= n; i++) adj[i] = (int*)malloc(deg[i] * sizeof(int));
    for (int i = 0; i < edgesSize; i++) {
        int u = edges[i][0], v = edges[i][1];
        adj[u][ptr[u]++] = v;
        adj[v][ptr[v]++] = u;
    }

    bool* visited = (bool*)calloc(n + 1, sizeof(bool));
    int* q_node = (int*)malloc((n + 1) * sizeof(int));
    int* q_time = (int*)malloc((n + 1) * sizeof(int));
    double* q_prob = (double*)malloc((n + 1) * sizeof(double));
    int head = 0, tail = 0;

    q_node[tail] = 1; q_time[tail] = 0; q_prob[tail] = 1.0; tail++;
    visited[1] = true;
    double ans = 0.0;

    while (head < tail) {
        int u = q_node[head], time = q_time[head];
        double p = q_prob[head++];

        int unvisited = 0;
        for (int i = 0; i < deg[u]; i++) {
            if (!visited[adj[u][i]]) unvisited++;
        }

        if (u == target) {
            if (time == t || (time < t && unvisited == 0)) ans = p;
            else ans = 0.0;
            break;
        }
        if (time >= t) continue;

        if (unvisited > 0) {
            double nextP = p / unvisited;
            for (int i = 0; i < deg[u]; i++) {
                int v = adj[u][i];
                if (!visited[v]) {
                    visited[v] = true;
                    q_node[tail] = v; q_time[tail] = time + 1; q_prob[tail] = nextP; tail++;
                }
            }
        }
    }

    for (int i = 1; i <= n; i++) free(adj[i]);
    free(adj); free(deg); free(ptr); free(visited);
    free(q_node); free(q_time); free(q_prob);
    return ans;
}

